<?php declare(strict_types=1); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Booking messages</title><style>body{font-family:var(--villa-font-body);background:#f5f7f5;color:var(--villa-text);margin:0}.wrap{max-width:800px;margin:35px auto;padding:0 18px}.panel{background:white;border:1px solid #e7ece8;border-radius:14px;padding:20px;margin:12px 0}.msg{padding:12px;border-radius:10px;background:#f0f5f1;margin:10px 0;max-width:80%}.mine{margin-left:auto;background:#e6f2eb}textarea{width:100%;box-sizing:border-box;min-height:90px;padding:12px;border:1px solid #dfe6e0;border-radius:8px;font:inherit;}button{background:#176b50;color:var(--villa-text);border:0;border-radius:8px;padding:12px 17px;font-weight:var(--villa-body-weight);}.muted{color:var(--villa-text);font-size:var(--villa-body-size);}</style><?php require APP_ROOT . '/views/site/partials/account-theme.php'; ?></head><body><main class="wrap"><h1><?= e($booking['title']) ?> · Messages</h1><p class="muted"><?= e($booking['booking_code']) ?> · <?= e($booking['guest_name']) ?></p><section class="panel"><?php foreach($messages as $message): ?><div class="msg <?= (int)$message['sender_user_id']===(int)$user['id']?'mine':'' ?>"><strong><?= (int)$message['sender_user_id']===(int)$user['id']?'You':e($message['sender_name']) ?></strong><p><?= nl2br(e($message['body'])) ?></p><small class="muted"><?= e($message['created_at']) ?></small></div><?php endforeach; ?><?php if(!$messages): ?><p>No messages yet. You can send the first message.</p><?php endif; ?></section><form class="panel" method="post" action="<?= e(app_url('/account/messages/send')) ?>"><?= csrf_field() ?><input type="hidden" name="booking_id" value="<?= (int)$booking['id'] ?>"><label>Your message</label><textarea name="body" maxlength="5000" required></textarea><p><button type="submit">Send message</button></p></form><p><a href="<?= e(app_url(($user['role']??'')==='vendor'?'/vendor':'/account/bookings')) ?>">Go back</a></p><?php require APP_ROOT . '/views/site/partials/logout-button.php'; ?></main></body></html>